{"shader": "float4 render(float2 uv)
{
	float2 texel = 1.0 / uv_size;
	float2 d = uv - float2(0.5, 0.5);
	float away = saturate((length(d) - p2) / max(0.0001, 0.5 - p2));
	float spread = away * p1;

	float4 sum = sample_at(uv);
	sum += sample_at(uv + float2(-1.0, -1.0) * texel * spread);
	sum += sample_at(uv + float2( 1.0, -1.0) * texel * spread);
	sum += sample_at(uv + float2(-1.0,  1.0) * texel * spread);
	sum += sample_at(uv + float2( 1.0,  1.0) * texel * spread);
	sum += sample_at(uv + float2( 0.0, -1.0) * texel * spread);
	sum += sample_at(uv + float2( 0.0,  1.0) * texel * spread);
	sum += sample_at(uv + float2(-1.0,  0.0) * texel * spread);
	sum += sample_at(uv + float2( 1.0,  0.0) * texel * spread);
	return sum / 9.0;
}
", "p1": 14.0, "p2": 0.16, "p3": 0.0, "p4": 0.0}
